package dev.gbppimentel.snapcompanion;
import org.junit.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;
public class OcrDeliveryTest {
 private OcrDelivery delivery(AtomicInteger success,AtomicInteger failure,AtomicInteger released){return new OcrDelivery(new OcrEngine.Callback(){public void success(List<LiveReading.Word> words,long milliseconds){success.incrementAndGet();}public void failure(String reason){failure.incrementAndGet();}},released::incrementAndGet);}
 @Test public void laterStageExceptionDeliversFailureAndReleasesTheBusySlot(){var success=new AtomicInteger();var failure=new AtomicInteger();var released=new AtomicInteger();var delivery=delivery(success,failure,released);Runnable later=()->delivery.run(()->{throw new IllegalArgumentException("invalid crop fixture");});delivery.run(()->{});assertEquals(0,released.get());later.run();assertEquals(0,success.get());assertEquals(1,failure.get());assertEquals(1,released.get());delivery.failure("late failure");delivery.run(()->fail("No work after completion"));assertEquals(1,released.get());}
 @Test public void duplicateTerminalCallbacksCannotReleaseAnotherInference(){var success=new AtomicInteger();var failure=new AtomicInteger();var released=new AtomicInteger();var delivery=delivery(success,failure,released);delivery.success(List.of(),20);delivery.success(List.of(),20);delivery.failure("late");assertEquals(1,success.get());assertEquals(0,failure.get());assertEquals(1,released.get());}
 @Test public void callbackExceptionStillReleasesExactlyOnce(){var released=new AtomicInteger();var delivery=new OcrDelivery(new OcrEngine.Callback(){public void success(List<LiveReading.Word>w,long ms){throw new IllegalStateException();}public void failure(String s){fail("Already delivered");}},released::incrementAndGet);delivery.run(()->delivery.success(List.of(),1));assertEquals(1,released.get());}
 @Test public void racingSuccessAndFailureHaveOneTerminalOwner()throws Exception{var success=new AtomicInteger();var failure=new AtomicInteger();var released=new AtomicInteger();var delivery=delivery(success,failure,released);var work=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{var a=work.submit(()->{try{start.await();delivery.success(List.of(),1);}catch(InterruptedException e){throw new RuntimeException(e);}});var b=work.submit(()->{try{start.await();delivery.failure("fixture");}catch(InterruptedException e){throw new RuntimeException(e);}});start.countDown();a.get(5,TimeUnit.SECONDS);b.get(5,TimeUnit.SECONDS);assertEquals(1,success.get()+failure.get());assertEquals(1,released.get());}finally{work.shutdownNow();}}
}
